local TooltipLabel = New("TextLabel", {
	Parent = TooltipInner,
	Text = "",
	TextColor3 = "FontColor",
	TextStrokeTransparency = 0,
	BackgroundTransparency = 1,
	AutomaticSize = Enum.AutomaticSize.XY,
	Size = UDim2.fromOffset(0, 14),
