	local KEY_NONE = "None"
	local activeCapture
	Library:GiveSignal(UserInputService.InputBegan:Connect(function(input)
		if activeCapture and input.UserInputType == Enum.UserInputType.Keyboard then
			local name = input.KeyCode == Enum.KeyCode.Escape and KEY_NONE or input.KeyCode.Name
			activeCapture(name)
			activeCapture = nil
		end
	end))

	-- field editor; writes straight back into step.data[field.Key] on edit. no hardcoded font.
	local function makeEditor(parent, field, step)
		local kind = field.Kind
		if kind == "number" or kind == "text" then
			local box = New("TextBox", {
				Parent = parent,
				Text = tostring(step.data[field.Key] ~= nil and step.data[field.Key] or (field.Default ~= nil and field.Default or "")),
				PlaceholderText = field.Placeholder or "",
				PlaceholderColor3 = Color3.fromRGB(90, 90, 90),
				TextColor3 = "FontColor",
				TextStrokeTransparency = 0.5,
				BackgroundColor3 = "Element",
				BorderColor3 = "ElementBorder",
				BorderSizePixel = 1,
				ClearTextOnFocus = false,
				Size = UDim2.new(0, math.clamp(field.Width or 96, 60, 104), 0, 17),
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 12,
			})
			New("UIPadding", { Parent = box, PaddingLeft = UDim.new(0, 5) })
			box.FocusLost:Connect(function()
				if kind == "number" then
					local n = tonumber(box.Text)
					if n == nil then
						n = field.Default or 0
					end
					step.data[field.Key] = n
					box.Text = tostring(n)
				else
					step.data[field.Key] = box.Text
				end
			end)
			return box
		elseif kind == "choice" then
			local options = field.Options or { "a", "b" }
			step.data[field.Key] = step.data[field.Key] or field.Default or options[1]
			local btn = New("TextButton", {
				Parent = parent,
				Text = tostring(step.data[field.Key]),
				TextColor3 = "FontColor",
				TextStrokeTransparency = 0.5,
				BackgroundColor3 = "Element",
				BorderColor3 = "ElementBorder",
				BorderSizePixel = 1,
				AutoButtonColor = false,
				Size = UDim2.new(0, math.clamp(field.Width or 96, 60, 104), 0, 17),
				TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 12,
			})
			New("UIPadding", { Parent = btn, PaddingLeft = UDim.new(0, 5) })
			btn.MouseButton1Click:Connect(function()
				local idx = table.find(options, step.data[field.Key]) or 0
				local nextOpt = options[(idx % #options) + 1]
				step.data[field.Key] = nextOpt
				btn.Text = tostring(nextOpt)
			end)
			return btn
		elseif kind == "key" then
			step.data[field.Key] = step.data[field.Key] or field.Default or KEY_NONE
			local btn = New("TextButton", {
				Parent = parent,
				Text = "[" .. tostring(step.data[field.Key]) .. "]",
				TextColor3 = "FontColor",
				TextStrokeTransparency = 0.5,
				BackgroundColor3 = "Element",
				BorderColor3 = "ElementBorder",
				BorderSizePixel = 1,
				AutoButtonColor = false,
				Size = UDim2.new(0, field.Width or 58, 0, 14),
				ZIndex = 12,
			})
			btn.MouseButton1Click:Connect(function()
				btn.Text = "[...]"
				activeCapture = function(name)
					step.data[field.Key] = name
					btn.Text = "[" .. name .. "]"
				end
			end)
			return btn
		end
	end

	local function indexOf(s)
		for i, st in ipairs(Macro.Steps) do
			if st == s then
				return i
			end
		end
		return nil
	end
	local function renumber()
		for i, st in ipairs(Macro.Steps) do
			st.Row.LayoutOrder = i
			if st._index then
				st._index.Text = tostring(i)
			end
			-- striping is for dense read only tables; this one has hover, inline boxes and buttons, where it is just noise
			st.Row.BackgroundColor3 = Library.Scheme.Element
		end
	end

	local function macroPointerY()
		local raw = UserInputService:GetMouseLocation().Y
		local adjusted = raw - GuiService:GetGuiInset().Y
		local top = listBody.AbsolutePosition.Y
		local bottom = top + listBody.AbsoluteSize.Y
		if adjusted >= top and adjusted <= bottom then
			return adjusted
		end
		if raw >= top and raw <= bottom then
			return raw
		end
		return adjusted
	end

	-- the landing slot is whichever row the pointer is above the middle of, so dropping past the last one appends
	local function macroDropSlot()
		local y = macroPointerY()
		for index, st in ipairs(Macro.Steps) do
			local row = st.Row
			if row and row.Parent and row.Visible and y < row.AbsolutePosition.Y + row.AbsoluteSize.Y / 2 then
				return index
			end
		end
		return #Macro.Steps + 1
	end

	local function macroPaintDrop(slot)
		local steps = Macro.Steps
		for index, st in ipairs(steps) do
			if st.Row and st.Row.Parent then
				st.Row.LayoutOrder = index >= slot and index + 1 or index
			end
		end
		Spacer.LayoutOrder = slot
		Spacer.Visible = true
		local anchor = (steps[slot] or steps[#steps] or {}).Row
		if not (anchor and anchor.Parent) then
			DropLine.Visible = false
			return
		end
		local y = steps[slot] and anchor.AbsolutePosition.Y or (anchor.AbsolutePosition.Y + anchor.AbsoluteSize.Y)
		DropLine.Position = UDim2.fromOffset(3, y - listBody.AbsolutePosition.Y - 1)
		DropLine.Visible = true
	end

	local function macroAutoScroll()
		local y = macroPointerY()
		local top = listBody.AbsolutePosition.Y
		local bottom = top + listBody.AbsoluteSize.Y
		local step = 0
		if y < top + MACRO_DRAG_EDGE then
			step = -MACRO_DRAG_SCROLL
		elseif y > bottom - MACRO_DRAG_EDGE then
			step = MACRO_DRAG_SCROLL
		end
		if step ~= 0 then
			local maxScroll = math.max(0, Scroll.AbsoluteCanvasSize.Y - (Scroll.AbsoluteWindowSize or Scroll.AbsoluteSize).Y)
			Scroll.CanvasPosition = Vector2.new(0, math.clamp(Scroll.CanvasPosition.Y + step, 0, maxScroll))
		end
	end

	local function macroClearDrag()
		DropLine.Visible = false
		Spacer.Visible = false
		if mDrag.ghost then
			pcall(function()
				mDrag.ghost:Destroy()
			end)
			mDrag.ghost = nil
		end
		for index, st in ipairs(Macro.Steps) do
			if st.Row and st.Row.Parent then
				st.Row.LayoutOrder = index
				st.Row.Visible = true
			end
		end
		renumber()
	end

	local function macroBeginDrag(index)
		if mDrag.index or #Macro.Steps < 2 then
			return
		end
		mDrag.index, mDrag.target = index, index
		local row = Macro.Steps[index] and Macro.Steps[index].Row
		if row then
			-- the row rides the cursor so it is obvious what is being moved, and the gap shows where it lands
			local ok, ghost = pcall(function()
				return row:Clone()
			end)
			if ok and ghost then
				ghost.Name = "DragGhost"
				ghost.LayoutOrder = 0
				ghost.Visible = true
				ghost.BackgroundTransparency = 0.15
				ghost.AnchorPoint = Vector2.new(0, 0.5)
				ghost.Size = UDim2.fromOffset(row.AbsoluteSize.X, row.AbsoluteSize.Y)
				ghost.ZIndex = 60
				ghost.Parent = shell.Outline
				mDrag.ghost = ghost
			end
			row.Visible = false
		end
		task.spawn(function()
			while mDrag.index == index do
				mDrag.target = macroDropSlot()
				macroPaintDrop(mDrag.target)
				macroAutoScroll()
				if mDrag.ghost then
					mDrag.ghost.Position = UDim2.fromOffset(
						listBody.AbsolutePosition.X - shell.Outline.AbsolutePosition.X + 2,
						macroPointerY() - shell.Outline.AbsolutePosition.Y
					)
				end
				task.wait(MACRO_DRAG_POLL)
			end
		end)
	end

	local function macroEndDrag(commit)
		local from, to = mDrag.index, mDrag.target
		mDrag.index, mDrag.target = nil, nil
		macroClearDrag()
		if not (commit and from and to) then
			return
		end
		-- pulling a row out shifts everything below it up, so dropping below where it started lands one short
		if to > from then
			to -= 1
		end
		if to == from or to < 1 or to > #Macro.Steps then
			return
		end
		local step = table.remove(Macro.Steps, from)
		table.insert(Macro.Steps, to, step)
		renumber()
	end

	local function buildMenu()
		for _, c in MenuInner:GetChildren() do
			if c:IsA("TextButton") then
				c:Destroy()
			end
		end
		for order, name in ipairs(Macro._order) do
			local cfg = Macro.StepTypes[name]
			local b = New("TextButton", {
				Parent = MenuInner,
				Text = cfg.Label or name,
				TextColor3 = cfg.Color or "FontColor",
				TextStrokeTransparency = 0.5,
				BackgroundColor3 = "Element",
				BorderColor3 = "ElementBorder",
				BorderSizePixel = 1,
				AutoButtonColor = false,
				Size = UDim2.new(1, 0, 0, 15),
				LayoutOrder = order,
				ZIndex = 42,
			})
			b.MouseButton1Click:Connect(function()
				Macro:AddStep(name)
				Menu.Visible = false
			end)
		end
	end

	local function makeRow(step)
		local row = New("Frame", {
			Parent = Scroll,
			Name = "Step",
			BackgroundColor3 = "Element",
			BorderColor3 = "ElementBorder",
			BorderSizePixel = 1,
			Size = UDim2.new(1, 0, 0, MACRO_ROW_H),
		})
		step.Row = row
		-- a frame only sees what its buttons and boxes did not take, so the whole row drags without stealing their clicks
		row.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				macroBeginDrag(indexOf(step))
			end
		end)
		local grip = New("Frame", {
			Parent = row,
			Name = "Grip",
			BackgroundColor3 = "Accent",
			BorderSizePixel = 0,
			Size = UDim2.new(0, 2, 1, 0),
			Visible = false,
			ZIndex = 11,
		})
		step._index = New("TextLabel", {
			Parent = row,
			Name = "Index",
			Text = "",
			TextColor3 = "DimColor",
			TextStrokeTransparency = 0.6,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(4, 0),
			Size = UDim2.fromOffset(14, MACRO_ROW_H),
			TextSize = 10,
			TextXAlignment = Enum.TextXAlignment.Right,
			ZIndex = 11,
		})
		row.MouseEnter:Connect(function()
			grip.Visible = true
			row.BackgroundColor3 = Library.Scheme.Pop
			row.BorderColor3 = Library.Scheme.Accent
		end)
		row.MouseLeave:Connect(function()
			grip.Visible = false
			row.BackgroundColor3 = Library.Scheme.Element
			row.BorderColor3 = Library.Scheme.ElementBorder
		end)
		local cfg = Macro.StepTypes[step.type] or { Label = step.type }
		-- the type reads as a coloured chip rather than loose text, which is what gives the list a column to scan down
		local badgeColour = cfg.Color or Library.Scheme.FontColor
		local badge = New("Frame", {
			Parent = row,
			Name = "Badge",
			BackgroundColor3 = badgeColour,
			BackgroundTransparency = 0.62,
			BorderColor3 = badgeColour,
			BorderSizePixel = 1,
			Position = UDim2.fromOffset(21, 4),
			Size = UDim2.fromOffset(84, MACRO_ROW_H - 8),
			ZIndex = 11,
		})
		-- the label cannot be the same hue as the fill it sits on, which is what made these unreadable
		New("TextLabel", {
			Parent = badge,
			Name = "Type",
			Text = cfg.Label or step.type,
			TextColor3 = Color3.fromRGB(244, 244, 244),
			TextStrokeTransparency = 0.55,
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			TextSize = 11,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 12,
		})
		local left = New("Frame", {
			Parent = row,
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			Position = UDim2.fromOffset(111, 0),
			Size = UDim2.new(1, -169, 1, 0),
			ZIndex = 11,
		})
		New("UIListLayout", {
			Parent = left,
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 4),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		})
		for _, field in ipairs(cfg.Fields or {}) do
			makeEditor(left, field, step)
		end
		local right = New("Frame", {
			Parent = row,
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -3, 0.5, 0),
			Size = UDim2.fromOffset(54, 16),
			ZIndex = 11,
		})
		New("UIListLayout", {
			Parent = right,
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 2),
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
			VerticalAlignment = Enum.VerticalAlignment.Center,
		})
		local function actBtn(text, order, colour)
			local b = New("TextButton", {
				Parent = right,
				Text = text,
				TextColor3 = colour or "DimColor",
				TextStrokeTransparency = 0.5,
				TextSize = 11,
				BackgroundColor3 = "Dark",
				BorderColor3 = "DarkBorder",
				BorderSizePixel = 1,
				AutoButtonColor = false,
				Size = UDim2.fromOffset(16, 16),
				LayoutOrder = order,
				ZIndex = 12,
			})
			b.MouseEnter:Connect(function()
				b.BackgroundColor3 = Library.Scheme.Pop
				b.TextColor3 = colour or Library.Scheme.FontColor
			end)
			b.MouseLeave:Connect(function()
				b.BackgroundColor3 = Library.Scheme.Dark
				b.TextColor3 = colour or Library.Scheme.DimColor
			end)
			return b
		end
		local up, down = actBtn("▲", 1), actBtn("▼", 2)
		up.MouseButton1Click:Connect(function()
			Macro:MoveStep(step, -1)
		end)
		down.MouseButton1Click:Connect(function()
			Macro:MoveStep(step, 1)
		end)
		-- quiet until the row is under the cursor, so eight rows are not eight sets of buttons competing with the values
		local function fade(on)
			for _, b in right:GetChildren() do
				if b:IsA("TextButton") then
					b.TextTransparency = on and 0 or 0.45
					b.BackgroundTransparency = on and 0 or 0.5
				end
			end
		end
		row.MouseEnter:Connect(function()
			fade(true)
		end)
		row.MouseLeave:Connect(function()
			fade(false)
		end)
		fade(false)
		actBtn("X", 3, Color3.fromRGB(215, 90, 90)).MouseButton1Click:Connect(function()
			Macro:RemoveStep(step)
		end)
		return row
	end

	function Macro:RegisterStepType(name, config)
		config = config or {}
		if not self.StepTypes[name] then
			table.insert(self._order, name)
		end
		self.StepTypes[name] = config
		buildMenu()
		return self
	end

	function Macro:AddStep(typeKey, data)
		local cfg = self.StepTypes[typeKey]
		if not cfg then
			return nil
		end
		local step = { type = typeKey, data = {} }
		for _, field in ipairs(cfg.Fields or {}) do
			if data and data[field.Key] ~= nil then
				step.data[field.Key] = data[field.Key]
			else
				step.data[field.Key] = field.Default
			end
		end
		if data then
			for k, v in data do
				if k ~= "type" and step.data[k] == nil then
					step.data[k] = v
				end
			end
		end
		makeRow(step)
		table.insert(self.Steps, step)
		renumber()
		return step
	end

	function Macro:RemoveStep(ref)
		local i = type(ref) == "number" and ref or indexOf(ref)
		if not i then
			return
		end
		local step = self.Steps[i]
		if step and step.Row then
			pcall(function()
				step.Row:Destroy()
			end)
		end
		table.remove(self.Steps, i)
		renumber()
	end

	function Macro:MoveStep(ref, delta)
		local i = type(ref) == "number" and ref or indexOf(ref)
		if not i then
			return
		end
		local j = i + delta
		if j < 1 or j > #self.Steps then
			return
		end
		self.Steps[i], self.Steps[j] = self.Steps[j], self.Steps[i]
		renumber()
	end

	function Macro:GetSequence()
		local out = {}
		for _, st in ipairs(self.Steps) do
			local s = { type = st.type }
			for k, v in st.data do
				s[k] = v
			end
			table.insert(out, s)
		end
		return out
	end

	function Macro:Clear()
		for _, st in ipairs(self.Steps) do
			if st.Row then
				pcall(function()
					st.Row:Destroy()
				end)
			end
		end
		table.clear(self.Steps)
		renumber()
		NameBox.Text = ""
		selectedName = nil
		SavedBtn.Text = "saved macros"
		if self.OnClear then
			Library:SafeCallback(self.OnClear)
		end
	end

	function Macro:SetSequence(list)
		self:Clear()
		if type(list) == "table" then
			for _, s in ipairs(list) do
				if type(s) == "table" and s.type then
					self:AddStep(s.type, s)
				end
			end
		end
	end

	function Macro:GetName()
		return NameBox.Text
	end
	function Macro:SetName(name)
		NameBox.Text = tostring(name or "")
	end
	function Macro:SetSavedList(names)
		savedNames = names or {}
		if #savedNames == 0 then
			SavedBtn.Text = "saved macros"
			selectedName = nil
		end
		buildSavedMenu()
	end

	function Macro:Save()
		if self.OnSave then
			Library:SafeCallback(self.OnSave, self:GetSequence())
		end
	end
	function Macro:Load(name)
		name = name or selectedName or NameBox.Text
		if self.OnLoad then
			local seq = self.OnLoad(name)
			if type(seq) == "table" then
				-- SetSequence->Clear wipes the name/selection; restore the loaded macro's identity so it shows + Save overwrites it
				local loaded = NameBox.Text ~= "" and NameBox.Text or name
				self:SetSequence(seq)
				if loaded ~= "" then
					NameBox.Text = loaded
					selectedName = loaded
					SavedBtn.Text = loaded
					if self.OnSelect then
						Library:SafeCallback(self.OnSelect, loaded)
					end
				end
			end
		end
	end
	function Macro:Delete(name)
		name = name or selectedName or NameBox.Text
		if name ~= "" and self.OnDelete then
			Library:SafeCallback(self.OnDelete, name)
		end
	end

	function Macro:SetVisible(v)
		shell.Outline.Visible = v and true or false
		if not v then
			Menu.Visible = false
		end
	end
	function Macro:Show()
		self:SetVisible(true)
	end
	function Macro:Hide()
		self:SetVisible(false)
	end
	function Macro:Toggle()
		self:SetVisible(not shell.Outline.Visible)
	end
	function Macro:Resize(dx, dy)
		return setSize(shell.Outline.Size.X.Offset + (dx or 0), shell.Outline.Size.Y.Offset + (dy or 0))
	end

	CloseBtn.MouseButton1Click:Connect(function()
		Macro:Hide()
	end)
	AddBtn.MouseButton1Click:Connect(function()
		Menu.Visible = not Menu.Visible
	end)
	SaveBtn.MouseButton1Click:Connect(function()
		Macro:Save()
	end)
	LoadBtn.MouseButton1Click:Connect(function()
		Macro:Load()
	end)
	DeleteBtn.MouseButton1Click:Connect(function()
		Macro:Delete()
	end)
	ClearBtn.MouseButton1Click:Connect(function()
		Macro:Clear()
	end)

	local GateScrim = New("TextButton", {
		Parent = shell.Outline,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		AutoButtonColor = false,
		Visible = false,
		ZIndex = 39,
	})
	local GatePanel = New("Frame", {
		Parent = shell.Outline,
		BackgroundColor3 = "Dark",
		BorderColor3 = "Accent",
		BorderSizePixel = 1,
		Position = UDim2.fromOffset(55, 72),
		Size = UDim2.fromOffset(226, 46),
		Visible = false,
		ZIndex = 40,
	})
	New("TextLabel", {
		Parent = GatePanel,
		Text = "run only while",
		TextColor3 = "DimColor",
		TextStrokeTransparency = 0.7,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(6, 2),
		Size = UDim2.fromOffset(120, 12),
		TextSize = 10,
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 41,
	})
	local function gateCell(x, w, text)
		return New("TextButton", {
			Parent = GatePanel,
			Text = text,
			TextColor3 = "FontColor",
			TextStrokeTransparency = 0.4,
			BackgroundColor3 = "Element",
			BorderColor3 = "ElementBorder",
			BorderSizePixel = 1,
			AutoButtonColor = false,
			Position = UDim2.fromOffset(x, 16),
			Size = UDim2.fromOffset(w, 16),
			TextSize = 11,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 41,
		})
	end
	local GateVarBtn = gateCell(6, 96, "-")
	local GateOpBtn = gateCell(106, 34, ">=")
	local GateValBox = New("TextBox", {
		Parent = GatePanel,
		Text = "70",
		TextColor3 = "FontColor",
		TextStrokeTransparency = 0.4,
		BackgroundColor3 = "Element",
		BorderColor3 = "ElementBorder",
		BorderSizePixel = 1,
		ClearTextOnFocus = false,
		Position = UDim2.fromOffset(144, 16),
		Size = UDim2.fromOffset(42, 16),
		TextSize = 11,
		ZIndex = 41,
	})
	local GateOffBtn = gateCell(190, 30, "clear")

	local gate = nil

	local function gateLabel()
		return gate and "Gate: on" or "Gate: off"
	end
	local function paintGate()
		GateBtn.Text = gateLabel()
		GateBtn.TextColor3 = Library.Scheme[gate and "Accent" or "FontColor"]
		local entry = nil
		for _, v in ipairs(gateVars) do
			if gate and v.label == gate.var then
				entry = v
			end
		end
		GateVarBtn.Text = (gate and gate.var) or (gateVars[1] and gateVars[1].label) or "-"
		GateOpBtn.Text = (gate and gate.op) or ((entry or gateVars[1] or {}).ops or { ">=" })[1] or ">="
		GateValBox.Text = tostring((gate and gate.value) or 70)
	end
	local function varIndex(label)
		for i, v in ipairs(gateVars) do
			if v.label == label then
				return i
			end
		end
		return 1
	end
	local function ensureGate()
		if not gate then
			local first = gateVars[1]
			gate = { var = first and first.label or "", op = ((first or {}).ops or { ">=" })[1], value = tonumber(GateValBox.Text) or 70 }
		end
		return gate
	end

	GateBtn.MouseButton1Click:Connect(function()
		if #gateVars == 0 then
			return
		end
		if GatePanel.Visible then
			GatePanel.Visible = false
			GateScrim.Visible = false
			return
		end
		ensureGate()
		paintGate()
		-- a fixed spot runs off the edge as soon as the window is resized narrower
		local w = shell.Outline.AbsoluteSize.X
		GatePanel.Position = UDim2.fromOffset(math.max(4, math.min(4, w - 230)), 72)
		GateScrim.Visible = true
		GatePanel.Visible = true
	end)
	GateVarBtn.MouseButton1Click:Connect(function()
		local g = ensureGate()
		local nextVar = gateVars[(varIndex(g.var) % #gateVars) + 1]
		g.var = nextVar.label
		g.op = nextVar.ops[1]
		paintGate()
	end)
	GateOpBtn.MouseButton1Click:Connect(function()
		local g = ensureGate()
		local ops = (gateVars[varIndex(g.var)] or {}).ops or { ">=" }
		local at = 1
		for i, o in ipairs(ops) do
			if o == g.op then
				at = i
			end
		end
		g.op = ops[(at % #ops) + 1]
		paintGate()
	end)
	GateValBox.FocusLost:Connect(function()
		local g = ensureGate()
		g.value = tonumber(GateValBox.Text) or g.value
		paintGate()
	end)
	GateOffBtn.MouseButton1Click:Connect(function()
		gate = nil
		GatePanel.Visible = false
		GateScrim.Visible = false
		paintGate()
	end)
	GateScrim.MouseButton1Click:Connect(function()
		GatePanel.Visible = false
		GateScrim.Visible = false
	end)

	function Macro:GetGate()
		if not gate then
			return nil
		end
		return { var = gate.var, op = gate.op, value = gate.value }
	end
	function Macro:SetGate(cond)
		gate = (type(cond) == "table" and cond.var and { var = cond.var, op = cond.op or ">=", value = tonumber(cond.value) or 0 }) or nil
		GatePanel.Visible = false
		GateScrim.Visible = false
		paintGate()
	end
	paintGate()

	Library:GiveSignal(UserInputService.InputEnded:Connect(function(input)
		if mDrag.index and input.UserInputType == Enum.UserInputType.MouseButton1 then
			macroEndDrag(true)
		end
	end))

	Macro:RegisterStepType("wait", { Label = "Wait", Color = Color3.fromRGB(255, 170, 0), Fields = { { Key = "duration", Kind = "number", Default = 0.1, Width = 38 } } })
	Macro:RegisterStepType("keypress", {
		Label = "Key Press",
		Color = Color3.fromRGB(68, 221, 255),
		Fields = { { Key = "key", Kind = "key", Default = "None" }, { Key = "hold", Kind = "number", Default = 0.05, Width = 38 } },
	})
	Macro:RegisterStepType("click", { Label = "Click", Color = Color3.fromRGB(80, 255, 120), Fields = { { Key = "button", Kind = "choice", Options = { "left", "right" }, Default = "left", Width = 40 } } })
	Macro:RegisterStepType("comment", { Label = "Comment", Color = Color3.fromRGB(150, 150, 150), Fields = { { Key = "text", Kind = "text", Default = "", Width = 130 } } })

	if not Macro.OnSave then
		SaveBtn.Visible = false
	end
	if not Macro.OnLoad then
		LoadBtn.Visible = false
	end
	if not Macro.OnDelete then
		DeleteBtn.Visible = false
	end

	Library.MacroCreator = Macro
	return Macro
end

-- standalone, domain-neutral waypoint-path editor: a point is a position + consumer-named kind, every edit routes through callbacks
function Library:CreatePathEditor(info)
	info = info or {}
	local cb = {
		Read = info.Read,
		OnField = info.OnField,
		OnKind = info.OnKind,
		OnMove = info.OnMove,
		OnReorder = info.OnReorder,
		OnReorderMany = info.OnReorderMany,
		OnDelete = info.OnDelete,
		OnRecapture = info.OnRecapture,
		OnInsert = info.OnInsert,
		OnAppend = info.OnAppend,
		OnAppendAction = info.OnAppendAction,
		OnAppendBranch = info.OnAppendBranch,
		OnSave = info.OnSave,
		OnCondition = info.OnCondition,
		OnRefresh = info.OnRefresh,
		OnTest = info.OnTest,
		OnUndo = info.OnUndo,
		OnRedo = info.OnRedo,
		OnCopy = info.OnCopy,
		OnPaste = info.OnPaste,
		OnSpectate = info.OnSpectate,
		OnTeleport = info.OnTeleport,
		OnCopyPosition = info.OnCopyPosition,
		OnClose = info.OnClose,
	}
	local kinds = info.Kinds or {}
	-- optional per-point condition: consumer supplies Vars/Ops, the editor renders an "if" sub-line
	local condCfg = info.Condition
	local condVars = (condCfg and condCfg.Vars) or {}
	local condOps = (condCfg and condCfg.Ops) or { ">=", "<=" }
	local condUnit = (condCfg and condCfg.Unit) or ""
	local condDefault = (condCfg and condCfg.Default) or 0
	-- a var may be a plain label or a table carrying its own unit, operators and text value, so a name can be compared as well as a number
	local condVarLabels, condVarUnit, condVarOps, condVarText, condVarDefault = {}, {}, {}, {}, {}
	for _, v in condVars do
		local label = type(v) == "table" and v.label or v
		table.insert(condVarLabels, label)
		condVarUnit[label] = (type(v) == "table" and v.unit) or condUnit
		condVarOps[label] = (type(v) == "table" and v.ops) or condOps
		condVarText[label] = type(v) == "table" and v.text == true
		local declared = type(v) == "table" and v.default
		condVarDefault[label] = declared ~= nil and declared or (condVarText[label] and "" or condDefault)
	end
	info = Library:Validate(info, {
		Title = "path editor",
		Width = 620,
		Height = 360,
		Visible = false,
	})

	-- header cells and row cells read the same offsets, so a column can only be moved in one place
	local COL_TYPE, COL_POS, COL_AREA, COL_FIELDS, COL_ACTIONS = 26, 96, 194, 292, 110
	local ROW_HEIGHT, LINE_HEIGHT = 24, 20
	-- nesting is shown by shrinking the type chip into its own column, so the data columns never drift
	local INDENT_STEP, MAX_INDENT_LEVELS = 8, 3
	local DRAG_POLL = 0.02
	local DRAG_EDGE, DRAG_SCROLL, DRAG_SLOP = 22, 6, 8

	local kindByKey, kindOrder = {}, {}
	for _, k in ipairs(kinds) do
		kindByKey[k.key] = k
		table.insert(kindOrder, k.key)
	end
	local function nextKind(key)
		if #kindOrder == 0 then
			return key
		end
		local i = table.find(kindOrder, key) or 0
		return kindOrder[(i % #kindOrder) + 1]
	end
	local BASE_TITLE = info.Title

	local shell = MakeWindowShell(ScreenGui, UDim2.fromOffset(info.Width, info.Height), UDim2.fromOffset(360, 130), info.Title)
	shell.Outline.Visible = info.Visible and true or false

	local Header = New("Frame", {
		Parent = shell.Body,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 16),
		ZIndex = 5,
	})
	Library:MakeDraggable(shell.Outline, Header)

	local CloseBtn = New("TextButton", {
		Parent = shell.Body,
		Text = "X",
		TextColor3 = "DimColor",
		TextStrokeTransparency = 0.5,
		TextSize = 16,
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		Size = UDim2.fromOffset(16, 16),
		ZIndex = 8,
	})
	CloseBtn.MouseEnter:Connect(function()
		CloseBtn.TextColor3 = Library.Scheme.FontColor
	end)
	CloseBtn.MouseLeave:Connect(function()
		CloseBtn.TextColor3 = Library.Scheme.DimColor
	end)

	local Toolbar = New("Frame", {
		Parent = shell.Body,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(0, 18),
		Size = UDim2.new(1, 0, 0, 17),
		ZIndex = 6,
	})
	local function toolGroup(alignment, width)
		local holder = New("Frame", {
			Parent = Toolbar,
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(alignment == Enum.HorizontalAlignment.Right and 1 or 0, 0),
			Position = UDim2.fromScale(alignment == Enum.HorizontalAlignment.Right and 1 or 0, 0),
			Size = UDim2.new(width, 0, 1, 0),
			ZIndex = 6,
		})
		New("UIListLayout", {
			Parent = holder,
			FillDirection = Enum.FillDirection.Horizontal,
			HorizontalAlignment = alignment,
			Padding = UDim.new(0, 4),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		})
		return holder
	end
	local LeftTools = toolGroup(Enum.HorizontalAlignment.Left, 0.6)
	local RightTools = toolGroup(Enum.HorizontalAlignment.Right, 0.4)

	local function shade(value, fallback)
		return (typeof(value) == "Color3" and value) or Library.Scheme[value] or Library.Scheme[fallback]
	end
	-- omit hotText to leave the label alone on hover, which is what the colour-coded row buttons want
	local function hoverable(button, idle, hot, idleText, hotText)
		button.MouseEnter:Connect(function()
			button.BackgroundColor3 = shade(hot, "Pop")
			if hotText then
				button.TextColor3 = shade(hotText, "FontColor")
			end
		end)
		button.MouseLeave:Connect(function()
			button.BackgroundColor3 = shade(idle, "Element")
			if hotText then
				button.TextColor3 = shade(idleText, "FontColor")
			end
		end)
		return button
	end
	local function toolButton(parent, text, width, primary)
		return hoverable(
			New("TextButton", {
				Parent = parent,
				Text = text,
				TextColor3 = primary and "FontColor" or "DimColor",
				TextStrokeTransparency = 0.5,
				TextSize = 11,
				BackgroundColor3 = primary and "Pop" or "Element",
				BorderColor3 = "ElementBorder",
				BorderSizePixel = 1,
				AutoButtonColor = false,
				Size = UDim2.new(0, width, 0, 16),
				ZIndex = 7,
			}),
			primary and "Pop" or "Element",
			"Pop",
			primary and "FontColor" or "DimColor",
			"FontColor"
		)
	end
	local AddBtn = toolButton(LeftTools, "+ Add @ Me", 76, true)
	local ActionBtn = cb.OnAppendAction and toolButton(LeftTools, "+ Action", 58, false) or nil
	local BranchBtn = cb.OnAppendBranch and toolButton(LeftTools, "+ Branch", 60, false) or nil
	local CopyBtn = cb.OnCopy and toolButton(LeftTools, "Copy", 38, false) or nil
	local PasteBtn = cb.OnPaste and toolButton(LeftTools, "Paste", 40, false) or nil
	local TestBtn = cb.OnTest and toolButton(RightTools, "Test", 40, false) or nil
	local RefreshBtn = toolButton(RightTools, "Refresh", 52, false)
	local SaveBtn = toolButton(RightTools, "Save", 42, true)

	local _, _, listBody = MakePanel(shell.Body, UDim2.new(1, 0, 1, -39), UDim2.fromOffset(0, 39))

	-- a column header carries what the old glyph legend did, without a line of prose above every path
	local ColumnHeader = New("Frame", {
		Parent = listBody,
		BackgroundColor3 = "Dark",
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 17),
		ZIndex = 6,
	})
	-- matches the scroll's padding below, otherwise every header cell sits a few pixels off its column
	New("UIPadding", { Parent = ColumnHeader, PaddingLeft = UDim.new(0, 3), PaddingRight = UDim.new(0, 4) })
	local function headerCell(text, position, size, alignment)
		New("TextLabel", {
			Parent = ColumnHeader,
			Text = text,
			TextColor3 = "DimColor",
			TextStrokeTransparency = 0.7,
			BackgroundTransparency = 1,
			Position = position,
			Size = size,
			TextSize = 10,
			TextXAlignment = alignment or Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 7,
		})
	end
	headerCell("#", UDim2.fromOffset(8, 0), UDim2.fromOffset(18, 17))
	headerCell("TYPE", UDim2.fromOffset(COL_TYPE + 4, 0), UDim2.fromOffset(66, 17))
	headerCell("POSITION", UDim2.fromOffset(COL_POS + 4, 0), UDim2.fromOffset(94, 17))
	headerCell("AREA", UDim2.fromOffset(COL_AREA + 4, 0), UDim2.fromOffset(94, 17))
	headerCell("OPTIONS", UDim2.fromOffset(COL_FIELDS + 4, 0), UDim2.new(1, -(COL_FIELDS + COL_ACTIONS + 8), 0, 17))
	headerCell("ACTIONS", UDim2.new(1, -(COL_ACTIONS + 4), 0, 0), UDim2.fromOffset(COL_ACTIONS, 17), Enum.TextXAlignment.Right)

	local Scroll = New("ScrollingFrame", {
		Parent = listBody,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 18),
		Size = UDim2.new(1, 0, 1, -18),
		CanvasSize = UDim2.fromOffset(0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 3,
		ScrollBarImageColor3 = "Accent",
	})
	New("UIListLayout", { Parent = Scroll, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 3) })
	New("UIPadding", {
		Parent = Scroll,
		PaddingTop = UDim.new(0, 3),
		PaddingBottom = UDim.new(0, 4),
		PaddingLeft = UDim.new(0, 3),
		PaddingRight = UDim.new(0, 4),
	})

	local EmptyState = New("TextLabel", {
		Parent = Scroll,
		Name = "EmptyState",
		Text = "No points yet.\nUse + Add @ Me to drop one where you are standing.",
		TextColor3 = "DimColor",
		TextStrokeTransparency = 0.7,
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 48),
		TextSize = 11,
		TextWrapped = true,
		TextYAlignment = Enum.TextYAlignment.Center,
		LayoutOrder = 0,
		Visible = false,
	})

	local ResizeHandle = New("Frame", {
		Parent = shell.Outline,
		BackgroundColor3 = "Accent",
		BorderColor3 = "Border",
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -1, 1, -1),
		Size = UDim2.fromOffset(10, 10),
		ZIndex = 50,
		Active = true,
	})

	local DropLine = New("Frame", {
		Parent = listBody,
		Name = "DropLine",
		BackgroundColor3 = "Accent",
		BorderSizePixel = 0,
		Size = UDim2.new(1, -6, 0, 2),
		Position = UDim2.fromOffset(3, 0),
		ZIndex = 30,
		Visible = false,
	})
	-- the row that would be pushed aside is shown as a real gap, so the landing place is the shape of the thing landing
	local Spacer = New("Frame", {
		Parent = Scroll,
		Name = "DropSpacer",
		BackgroundColor3 = "Accent",
		BackgroundTransparency = 0.75,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -4, 0, ROW_HEIGHT),
		ZIndex = 2,
		Visible = false,
	})
	-- the picker's entries call back into PathEditor, which is built below them, so it is declared here or those calls read a nil global
	local PathEditor
	-- cycling a click at a time through thirty odd kinds is what made picking an action a chore, so they get a filtered list dismissed by anything outside it
	local KindScrim = New("TextButton", {
		Parent = shell.Outline,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		AutoButtonColor = false,
		Visible = false,
		ZIndex = 69,
	})
	local KindPicker = New("Frame", {
		Parent = shell.Outline,
		BackgroundColor3 = "Dark",
		BorderColor3 = "Accent",
		BorderSizePixel = 1,
		Size = UDim2.fromOffset(168, 214),
		Visible = false,
		ZIndex = 70,
	})
	local KindFilter = New("TextBox", {
		Parent = KindPicker,
		Text = "",
		PlaceholderText = "filter",
		TextColor3 = "FontColor",
		PlaceholderColor3 = "DimColor",
		TextStrokeTransparency = 0.5,
		BackgroundColor3 = "Element",
		BorderColor3 = "ElementBorder",
		BorderSizePixel = 1,
		ClearTextOnFocus = false,
		Position = UDim2.fromOffset(4, 4),
		Size = UDim2.new(1, -8, 0, 17),
		TextSize = 11,
		ZIndex = 71,
	})
	local KindScroll = New("ScrollingFrame", {
		Parent = KindPicker,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(4, 24),
		Size = UDim2.new(1, -8, 1, -28),
		CanvasSize = UDim2.fromOffset(0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 3,
		ScrollBarImageColor3 = "Accent",
		ZIndex = 71,
	})
	New("UIListLayout", { Parent = KindScroll, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 1) })
	-- the row buttons are sixteen pixels of target each, so the things you reach for least live behind a right click instead
	local RowScrim = New("TextButton", {
		Parent = shell.Outline,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		AutoButtonColor = false,
		Visible = false,
		ZIndex = 74,
	})
	local RowMenu = New("Frame", {
		Parent = shell.Outline,
		BackgroundColor3 = "Dark",
		BorderColor3 = "Accent",
		BorderSizePixel = 1,
		Size = UDim2.fromOffset(112, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Visible = false,
		ZIndex = 75,
	})
	New("UIListLayout", { Parent = RowMenu, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 1) })
	New("UIPadding", { Parent = RowMenu, PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 2) })

	local function closeRowMenu()
		RowMenu.Visible = false
		RowScrim.Visible = false
	end
	RowScrim.MouseButton1Click:Connect(closeRowMenu)
	RowScrim.MouseButton2Click:Connect(closeRowMenu)

	local function openRowMenu(index)
		for _, child in RowMenu:GetChildren() do
			if child:IsA("TextButton") then
				child:Destroy()
			end
		end
		local many = #PathEditor:SelectedIndices() > 1 and PathEditor.Selected[index] == true
		local entries = {
			{ text = "Spectate", tint = many and "DimColor" or "FontColor", off = many, act = function()
				PathEditor:Spectate(index)
			end },
		}
		if cb.OnTeleport then
			table.insert(entries, { text = "Teleport", tint = many and "DimColor" or "FontColor", off = many, act = function()
				PathEditor:Teleport(index)
			end })
		end
		if cb.OnCopyPosition then
			table.insert(entries, { text = "Copy Position", tint = many and "DimColor" or "FontColor", off = many, act = function()
				PathEditor:CopyPosition(index)
			end })
		end
		table.insert(entries, { text = "Delete", tint = Color3.fromRGB(255, 120, 120), act = function()
			if many then
				PathEditor:DeleteSelected()
			else
				PathEditor:Delete(index)
			end
		end })
		local order = 0
		for _, entry in entries do
			order += 1
			local item = hoverable(
				New("TextButton", {
					Parent = RowMenu,
					Text = entry.text,
					TextColor3 = entry.tint,
					TextStrokeTransparency = 0.4,
					BackgroundColor3 = "Element",
					BorderSizePixel = 0,
					AutoButtonColor = false,
					Size = UDim2.new(1, -4, 0, 17),
					TextSize = 11,
					LayoutOrder = order,
					ZIndex = 76,
				}),
				"Element",
				"Pop"
			)
			item.MouseButton1Click:Connect(function()
				if entry.off then
					return
				end
				closeRowMenu()
				entry.act()
			end)
			if entry.text == "Spectate" then
				-- any row's entry stops it, so you never have to find the one you started from
				item.MouseButton2Click:Connect(function()
					closeRowMenu()
					PathEditor:Spectate(nil)
				end)
			end
		end
		local pointer = UserInputService:GetMouseLocation() - Vector2.new(0, GuiService:GetGuiInset().Y)
		local x = pointer.X - shell.Outline.AbsolutePosition.X
		local y = pointer.Y - shell.Outline.AbsolutePosition.Y
		RowMenu.Position = UDim2.fromOffset(
			math.clamp(x, 0, math.max(0, shell.Outline.AbsoluteSize.X - 116)),
			math.clamp(y, 0, math.max(0, shell.Outline.AbsoluteSize.Y - (#entries * 18 + 8)))
		)
		RowMenu.Visible = true
		RowScrim.Visible = true
	end

	local pickerFor = nil

	local function closeKindPicker()
		pickerFor = nil
		KindPicker.Visible = false
		KindScrim.Visible = false
	end
	KindScrim.MouseButton1Click:Connect(function()
		closeKindPicker()
	end)

	local function paintKindPicker()
		for _, c in KindScroll:GetChildren() do
			if c:IsA("TextButton") then
				c:Destroy()
			end
		end
		local needle = KindFilter.Text:lower()
		local order = 0
		for _, key in kindOrder do
			local cfg = kindByKey[key] or {}
			local label = tostring(cfg.label or key)
			if needle == "" or label:lower():find(needle, 1, true) or key:lower():find(needle, 1, true) then
				order += 1
				local entry = New("TextButton", {
					Parent = KindScroll,
					Text = "",
					BackgroundColor3 = "Element",
					BorderSizePixel = 0,
					AutoButtonColor = false,
					Size = UDim2.new(1, 0, 0, 17),
					LayoutOrder = order,
					ZIndex = 72,
				})
				New("Frame", {
					Parent = entry,
					BackgroundColor3 = cfg.color or "FontColor",
					BorderSizePixel = 0,
					Size = UDim2.new(0, 3, 1, 0),
					ZIndex = 73,
				})
				New("TextLabel", {
					Parent = entry,
					Text = label,
					TextColor3 = cfg.color or "FontColor",
					TextStrokeTransparency = 0.4,
					BackgroundTransparency = 1,
					Position = UDim2.fromOffset(8, 0),
					Size = UDim2.new(1, -10, 1, 0),
					TextSize = 11,
					TextTruncate = Enum.TextTruncate.AtEnd,
					TextXAlignment = Enum.TextXAlignment.Left,
					ZIndex = 73,
				})
				entry.MouseEnter:Connect(function()
					entry.BackgroundColor3 = Library.Scheme.Pop
				end)
				entry.MouseLeave:Connect(function()
					entry.BackgroundColor3 = Library.Scheme.Element
				end)
				entry.MouseButton1Click:Connect(function()
					local at = pickerFor
					closeKindPicker()
					if at then
						PathEditor:SetKind(at, key)
					end
				end)
			end
		end
	end

	local function openKindPicker(index, button)
		if pickerFor == index then
			closeKindPicker()
			return
		end
		pickerFor = index
		KindFilter.Text = ""
		paintKindPicker()
		local x = button.AbsolutePosition.X - shell.Outline.AbsolutePosition.X
		local y = button.AbsolutePosition.Y - shell.Outline.AbsolutePosition.Y + button.AbsoluteSize.Y + 2
		local maxY = shell.Outline.AbsoluteSize.Y - KindPicker.AbsoluteSize.Y - 4
		local maxX = shell.Outline.AbsoluteSize.X - 172
		KindPicker.Position = UDim2.fromOffset(math.clamp(x, 2, math.max(2, maxX)), math.clamp(y, 2, math.max(2, maxY)))
		KindScrim.Visible = true
		KindPicker.Visible = true
	end
	KindFilter:GetPropertyChangedSignal("Text"):Connect(paintKindPicker)

	local drag = { index = nil, target = nil, ghost = nil }

	PathEditor = {
		Holder = shell.Outline,
		Scroll = Scroll,
		Header = Header,
		Title = shell.Title,
		ResizeHandle = ResizeHandle,
		Rows = {},
		Paints = {},
		Slots = {},
		Marks = {},
		Selected = {},
		Kinds = kinds,
	}
	local selectionAnchor = nil

	local setSize = Library:MakeResizable(shell.Outline, ResizeHandle, Vector2.new(520, 200), Vector2.new(980, 760))

	-- a field with a fixed set of answers gets its own popup, kept clear of the kind picker so neither can paint into the other's list
	local ChoiceScrim = New("TextButton", {
		Parent = shell.Outline,
		Text = "",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		AutoButtonColor = false,
		Visible = false,
		ZIndex = 73,
	})
	local ChoicePicker = New("Frame", {
		Parent = shell.Outline,
		BackgroundColor3 = "Dark",
		BorderColor3 = "Accent",
		BorderSizePixel = 1,
		Size = UDim2.fromOffset(168, 180),
		Visible = false,
		ZIndex = 74,
	})
	local ChoiceScroll = New("ScrollingFrame", {
		Parent = ChoicePicker,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(4, 4),
		Size = UDim2.new(1, -8, 1, -8),
		CanvasSize = UDim2.fromOffset(0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 3,
		ScrollBarImageColor3 = "Accent",
