	end
	ChoiceScrim.MouseButton1Click:Connect(closeChoicePicker)

	local function openChoicePicker(button, values, onPick)
		for _, c in ChoiceScroll:GetChildren() do
			if c:IsA("TextButton") then
				c:Destroy()
			end
		end
		local order = 0
		for _, value in values do
			order += 1
			local entry = hoverable(New("TextButton", {
				Parent = ChoiceScroll,
				Text = tostring(value),
				TextColor3 = "FontColor",
				TextStrokeTransparency = 0.4,
				BackgroundColor3 = "Element",
				BorderSizePixel = 0,
				AutoButtonColor = false,
				Size = UDim2.new(1, 0, 0, 17),
				TextSize = 11,
				TextTruncate = Enum.TextTruncate.AtEnd,
				LayoutOrder = order,
				ZIndex = 76,
			}), "Element", "Pop")
			entry.MouseButton1Click:Connect(function()
				closeChoicePicker()
				onPick(value)
			end)
		end
		local height = math.clamp(order * 18 + 8, 26, 180)
		ChoicePicker.Size = UDim2.fromOffset(168, height)
		local x = button.AbsolutePosition.X - shell.Outline.AbsolutePosition.X
		local y = button.AbsolutePosition.Y - shell.Outline.AbsolutePosition.Y + button.AbsoluteSize.Y + 2
		local maxY = shell.Outline.AbsoluteSize.Y - height - 4
		local maxX = shell.Outline.AbsoluteSize.X - 172
		ChoicePicker.Position = UDim2.fromOffset(math.clamp(x, 2, math.max(2, maxX)), math.clamp(y, 2, math.max(2, maxY)))
		ChoiceScrim.Visible = true
		ChoicePicker.Visible = true
	end

	-- inline field editor (number/text/choice); commits straight back through OnField on FocusLost
	local function makeEditor(parent, field, slot)
		if field.Kind == "choice" then
			local current = tostring(field.Value ~= nil and field.Value or (field.Default ~= nil and field.Default or ""))
			local btn
			btn = hoverable(New("TextButton", {
				Parent = parent,
				Text = current ~= "" and current or (field.Placeholder or "pick"),
				TextColor3 = current ~= "" and "FontColor" or "DimColor",
				TextStrokeTransparency = 0.5,
				BackgroundColor3 = "Element",
				BorderColor3 = "ElementBorder",
				BorderSizePixel = 1,
				AutoButtonColor = false,
				Size = UDim2.fromOffset(field.Width or 110, 16),
				TextSize = 11,
				TextTruncate = Enum.TextTruncate.AtEnd,
				ZIndex = 12,
			}), "Element", "Pop")
			btn.MouseButton1Click:Connect(function()
				-- a list that can change while the editor is open has to be asked for when the picker opens, not when the row was built
				local values = type(field.Values) == "function" and field.Values() or field.Values
				openChoicePicker(btn, values or {}, function(value)
					btn.Text = tostring(value)
					btn.TextColor3 = shade("FontColor", "FontColor")
					PathEditor:SetField(slot.i, field.Key, value)
				end)
			end)
			return btn
		end
		local baseWidth = field.Width or 44
		-- TextTruncate never touches PlaceholderText, so the box sits in a frame that clips and the frame is what grows
		local clip = New("Frame", {
			Parent = parent,
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			Size = UDim2.fromOffset(baseWidth, 16),
			ZIndex = 12,
		})
		local box = New("TextBox", {
			Parent = clip,
			Text = tostring(field.Value ~= nil and field.Value or (field.Default ~= nil and field.Default or "")),
			PlaceholderText = field.Placeholder or "",
			PlaceholderColor3 = Color3.fromRGB(90, 90, 90),
			TextColor3 = "FontColor",
			TextStrokeTransparency = 0.5,
			BackgroundColor3 = "Element",
			BorderColor3 = "ElementBorder",
			BorderSizePixel = 1,
			ClearTextOnFocus = false,
			Size = UDim2.fromScale(1, 1),
			TextSize = 11,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 12,
		})
		-- the box you are typing in grows to fit what is in it and stops where the row's buttons start, since a long value read as gibberish over the field beside it
		local function fitWidth()
			if not box:IsFocused() then
				return
			end
			local measured = baseWidth
			pcall(function()
				measured = TextService:GetTextSize(box.Text, box.TextSize, box.Font, Vector2.new(9999, 100)).X + 10
			end)
			local room = parent.AbsoluteSize.X - (clip.AbsolutePosition.X - parent.AbsolutePosition.X)
			clip.Size = UDim2.fromOffset(math.clamp(measured, baseWidth, math.max(baseWidth, room)), 16)
		end
		box.Focused:Connect(function()
			box.TextTruncate = Enum.TextTruncate.None
			fitWidth()
		end)
		box:GetPropertyChangedSignal("Text"):Connect(fitWidth)
		box.FocusLost:Connect(function()
			box.TextTruncate = Enum.TextTruncate.AtEnd
			clip.Size = UDim2.fromOffset(baseWidth, 16)
			local value = box.Text
			if field.Kind == "number" then
				-- a number field with no default is allowed to be blank, and blank is its own setting rather than 0
				local n = tonumber(box.Text)
				if n == nil then
					n = field.Default
				end
				value = n
				box.Text = n ~= nil and tostring(n) or ""
			end
			PathEditor:SetField(slot.i, field.Key, value)
		end)
		return box
	end

	-- var/op/value controls, shared by the per-point "only if" line and a branch row's inline editor
	local function makeConditionControls(parent, cond, slot, varWidth)
		local unitLabel
		local function unitFor()
			return condVarUnit[cond.var] or condUnit
		end
		local function cycleBtn(source, key, width, order)
			local function options()
				return type(source) == "function" and source() or source
			end
			local btn = hoverable(
				New("TextButton", {
					Parent = parent,
					Text = tostring(cond[key]),
					TextColor3 = "FontColor",
					TextStrokeTransparency = 0.5,
					BackgroundColor3 = "Dark",
					BorderColor3 = "ElementBorder",
					BorderSizePixel = 1,
					AutoButtonColor = false,
					Size = UDim2.fromOffset(width, 16),
					TextSize = 11,
					TextTruncate = Enum.TextTruncate.AtEnd,
					LayoutOrder = order,
					ZIndex = 12,
				}),
				"Dark",
				"Pop"
			)
			local function step(delta)
				local list = options()
				if #list == 0 then
					return
				end
				local at = table.find(list, cond[key])
				if delta > 0 then
					cond[key] = list[((at or 0) % #list) + 1]
				else
					cond[key] = list[(((at or 1) - 2) % #list) + 1]
				end
				btn.Text = tostring(cond[key])
				if unitLabel then
					unitLabel.Text = unitFor()
				end
				PathEditor:SetCondition(slot.i, cond)
			end
			btn.MouseButton1Click:Connect(function()
				step(1)
			end)
			btn.MouseButton2Click:Connect(function()
				step(-1)
			end)
			return btn
		end
		local function opsFor()
			return condVarOps[cond.var] or condOps
		end
		local function isText()
			return condVarText[cond.var] == true
		end
		local function defaultFor()
			local d = condVarDefault[cond.var]
			if d == nil then
				return isText() and "" or condDefault
			end
			return d
		end
		local varBtn = cycleBtn(condVarLabels, "var", varWidth or 96, 2)
		local opBtn = cycleBtn(opsFor, "op", 44, 3)
		local function valueWidth()
			return isText() and 96 or 38
		end
		local valClip = New("Frame", {
			Parent = parent,
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			Size = UDim2.fromOffset(valueWidth(), 16),
			LayoutOrder = 4,
			ZIndex = 12,
		})
		local valBox = New("TextBox", {
			Parent = valClip,
			Text = tostring(cond.value or 0),
			TextColor3 = "FontColor",
			TextStrokeTransparency = 0.5,
			BackgroundColor3 = "Element",
			BorderColor3 = "ElementBorder",
			BorderSizePixel = 1,
			ClearTextOnFocus = false,
			Size = UDim2.fromScale(1, 1),
			TextSize = 11,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 12,
		})
		-- a centred value wider than its box spilled out both sides over the op, so the box grows to its text and truncates only at the end of the line
		local function fitValue()
			local base = valueWidth()
			local measured = base
			pcall(function()
				measured = TextService:GetTextSize(valBox.Text, valBox.TextSize, valBox.Font, Vector2.new(9999, 100)).X + 10
			end)
			local after = unitLabel and unitLabel.AbsoluteSize.X > 0 and unitLabel.AbsoluteSize.X + 4 or 0
			local room = parent.AbsoluteSize.X - (valClip.AbsolutePosition.X - parent.AbsolutePosition.X) - after - 4
			valClip.Size = UDim2.fromOffset(math.clamp(measured, base, math.max(base, room)), 16)
		end
		valBox:GetPropertyChangedSignal("Text"):Connect(fitValue)
		valClip:GetPropertyChangedSignal("AbsolutePosition"):Connect(fitValue)
		parent:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitValue)
		valBox.Focused:Connect(function()
			valBox.TextTruncate = Enum.TextTruncate.None
		end)
		valBox.FocusLost:Connect(function()
			valBox.TextTruncate = Enum.TextTruncate.AtEnd
			if isText() then
				cond.value = valBox.Text
			else
				cond.value = tonumber(valBox.Text) or tonumber(cond.value) or 0
				valBox.Text = tostring(cond.value)
			end
			PathEditor:SetCondition(slot.i, cond)
		end)
		local lastText, lastUnit = isText(), unitFor()
		-- the previous var's parameters used to stay on screen, so "Day >= 30" swapped to Backpack read as a tool named 30; a value only survives a swap between vars that measure the same thing
		local function reconcileVar()
			local allowed = opsFor()
			local wantText, wantUnit = isText(), unitFor()
			local swapped = wantText ~= lastText or wantUnit ~= lastUnit or not table.find(allowed, cond.op)
			if not table.find(allowed, cond.op) then
				cond.op = allowed[1]
				opBtn.Text = tostring(cond.op)
			end
			if swapped then
				cond.value = defaultFor()
				valBox.Text = tostring(cond.value)
			end
			lastText, lastUnit = wantText, wantUnit
			fitValue()
			PathEditor:SetCondition(slot.i, cond)
		end
		varBtn.MouseButton1Click:Connect(reconcileVar)
		varBtn.MouseButton2Click:Connect(reconcileVar)
		unitLabel = New("TextLabel", {
			Parent = parent,
			Text = unitFor(),
			TextColor3 = "DimColor",
			TextStrokeTransparency = 0.6,
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromOffset(0, 16),
			TextSize = 11,
			LayoutOrder = 5,
			ZIndex = 12,
		})
		unitLabel:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitValue)
		fitValue()
	end

	local function makeConditionLine(row, point, slot, indent)
		local line = New("Frame", {
			Parent = row,
			Name = "Condition",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, LINE_HEIGHT),
			LayoutOrder = 2,
		})
		New("UIListLayout", {
			Parent = line,
			FillDirection = Enum.FillDirection.Horizontal,
			Padding = UDim.new(0, 4),
			VerticalAlignment = Enum.VerticalAlignment.Center,
		})
		New("UIPadding", { Parent = line, PaddingLeft = UDim.new(0, COL_TYPE + indent + 2), PaddingBottom = UDim.new(0, 3) })
		New("Frame", {
			Parent = line,
			BackgroundColor3 = "Accent",
			BorderSizePixel = 0,
			Size = UDim2.fromOffset(2, 12),
			LayoutOrder = 0,
		})
		New("TextLabel", {
			Parent = line,
			Text = "only if",
			TextColor3 = "DimColor",
			TextStrokeTransparency = 0.6,
			BackgroundTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.X,
